func SeparateParenGroups(paren_string string) []string {
    var groups []string
    currentGroup := ""
    groupStart := 0

    for i, char := range paren_string {
        if char == '(' {
            if groupStart != 0 {
                currentGroup = paren_string[groupStart:i]
                groups = append(groups, currentGroup)
                groupStart = i
            }
        } else if char == ')' {
            groupStart = i + 1
        }
    }

    currentGroup = paren_string[groupStart:]
    groups = append(groups, currentGroup)

    return groups
}

