func MeanAbsoluteDeviation(numbers []float64) float64 {
    n := len(numbers)
    if n == 0 {
        return 0.0
    }

    sum := 0.0
    for _, num := range numbers {
        sum += num
    }
    mean := sum / float64(n)

    deviationSum := 0.0
    for _, num := range numbers {
        deviationSum += math.Abs(num - mean)
    }

    return deviationSum / float64(n)
}

