func Intersperse(numbers []int, delimeter int) []int {
    if len(numbers) <= 1 {
        return numbers
    }

    sortedNums := make([]int, len(numbers))
    copy(sortedNums, numbers)
    sort.Ints(sortedNums)

    interspersed := make([]int, 0, len(numbers)*2-1)

    for i, num := range sortedNums {
        if i > 0 {
            interspersed = append(interspersed, delimeter)
        }
        interspersed = append(interspersed, num)
    }

    return interspersed
}

