func RollingMax(numbers []int) []int {
    rollingMax := make([]int, len(numbers))
    sortedNumbers := make([]int, len(numbers))

    copy(sortedNumbers, numbers)

    for i := 0; i < len(numbers); i++ {
        subset := sortedNumbers[:i+1]
        sort.Ints(subset)
        rollingMax[i] = subset[len(subset)-1]
    }

    return rollingMax
}

