func isPalindrome(s string) bool {
    for i := 0; i < len(s)/2; i++ {
        if s[i] != s[len(s)-1-i] {
            return false
        }
    }
    return true
}

func MakePalindrome(str string) string {
    if len(str) == 0 {
        return ""
    }

    for i := len(str) - 1; i >= 0; i-- {
        if isPalindrome(str[:i+1]) {
            return str + strings.Join(reverseStr(str[:i]), "")
        }
    }

    return str + strings.Join(reverseStr(str), "")
}

func reverseStr(s string) []string {
    var reversed []string
    for i := len(s) - 1; i >= 0; i-- {
        reversed = append(reversed, string(s[i]))
    }
    return reversed
}

