func RescaleToUnit(numbers []float64) []float64 {
    min := numbers[0]
    max := numbers[0]

    for _, num := range numbers {
        if num < min {
            min = num
        }
        if num > max {
            max = num
        }
    }

    scale := 1.0 / (max - min)
    rescaled := make([]float64, len(numbers))

    for i, num := range numbers {
        rescaled[i] = (num - min) * scale
    }

    return rescaled
}

