func FlipCase(str string) string {
	runes := []rune(str)
	for i := range runes {
		if 'a' <= runes[i] && runes[i] <= 'z' {
			runes[i] -= 32
		} else if 'A' <= runes[i] && runes[i] <= 'Z' {
			runes[i] += 32
		}
	}
	return string(runes)
}

