import (
	"sort"
)

func SortThird(l []int) []int {
	for i := 0; i < len(l); i += 3 {
		start := i
		end := i + 3
		if end > len(l) {
			end = len(l)
		}
		sort.Slice(l[start:end], func(a, b int) bool {
			return l[start+a] < l[start+b]
		})
	}
	return l
}

