func SortThird(l []int) []int {
    sortedValues := make([]int, 0)
    copyList := make([]int, len(l))
    copy(copyList, l)

    for i := 0; i < len(l); i++ {
        if i%3 == 0 {
            sortedValues = append(sortedValues, l[i])
        }
    }

    sort.Ints(sortedValues)

    for i := 0; i < len(l); i++ {
        if i%3 == 0 {
            copyList[i] = sortedValues[0]
            sortedValues = sortedValues[1:]
        }
    }

    return copyList
}

