func TriplesSumToZero(l []int) bool {
    n := len(l)
    if n < 3 {
        return false
    }

    for i := 0; i < n-2; i++ {
        seen := make(map[int]bool)
        target := -l[i]

        for j := i + 1; j < n; j++ {
            if seen[target-l[j]] {
                return true
            }
            seen[l[j]] = true
        }
    }

    return false
}

