import (
	"sort"
)

func TriplesSumToZero(l []int) bool {
    n := len(l)
    if n < 3 {
        return false
    }

    sort.Ints(l)

    for i := 0; i < n-2; i++ {
        left, right := i+1, n-1
        for left < right {
            sum := l[i] + l[left] + l[right]
            if sum == 0 {
                return true
            } else if sum < 0 {
                left++
            } else {
                right--
            }
        }
    }

    return false
}

