func Modp(n int, p int) int {
	if n == 0 {
		return 1
	}

	result := 2
	for i := 1; i < n; i++ {
		if result >= p {
			result %= p
		}
		result *= 2
	}

	if result >= p {
		result %= p
	}

	return result
}

