func Common(l1 []int, l2 []int) []int {
    sort.Ints(l1)
    sort.Ints(l2)

    var common []int
    i, j := 0, 0

    for i < len(l1) && j < len(l2) {
        if l1[i] == l2[j] {
            if (i == 0 || l1[i] != l1[i-1]) && (j == 0 || l2[j] != l2[j-1]) {
                common = append(common, l1[i])
            }
            i++
            j++
        } else if l1[i] < l2[j] {
            i++
        } else {
            j++
        }
    }

    return common
}

