func CorrectBracketing(brackets string) bool {
    stack := make([]rune, 0)
    bracketPairs := map[rune]rune{
        '(': ')',
    }

    for _, b := range brackets {
        if b == '(' {
            stack = append(stack, b)
        } else if b == ')' {
            if len(stack) == 0 || bracketPairs[stack[len(stack)-1]] != b {
                return false
            }
            stack = stack[:len(stack)-1]
        }
    }

    return len(stack) == 0
}

