func Pluck(arr []int) []int {
    smallestEven := -1
    smallestIndex := len(arr)

    seen := make(map[int]int)

    for i, num := range arr {
        if num%2 == 0 && (smallestEven == -1 || num < smallestEven || (num == smallestEven && i < smallestIndex)) {
            smallestEven = num
            smallestIndex = i
        }

        if _, exists := seen[num]; !exists {
            seen[num] = i
        }
    }

    if smallestEven == -1 {
        return []int{}
    }

    return []int{smallestEven, smallestIndex}
}

