func StrangeSortList(lst []int) []int {
    if len(lst) == 0 {
        return lst
    }

    sorted := make([]int, len(lst))
    min, max := 0, 0
    index := 0

    for len(lst) > 0 {
        if len(lst) == 1 {
            sorted[index] = lst[0]
            break
        }

        min, max = findMinAndMax(lst)
        sorted[index] = min
        sorted[len(lst)-1] = max

        lst = removeElement(lst, min)
        lst = removeElement(lst, max)

        index++
    }

    return sorted
}

func findMinAndMax(lst []int) (int, int) {
    min, max := lst[0], lst[0]

    for i := 1; i < len(lst); i++ {
        if lst[i] < min {
            min = lst[i]
        }
        if lst[i] > max {
            max = lst[i]
        }
    }

    return min, max
}

func removeElement(lst []int, elem int) []int {
    index := -1

    for i, val := range lst {
        if val == elem {
            index = i
            break
        }
    }

    if index == -1 {
        return lst
    }

    return append(lst[:index], lst[index+1:]...)
}

