func StrangeSortList(lst []int) []int {
    if len(lst) == 0 {
        return lst
    }

    min, max := lst[0], lst[0]
    seen := make(map[int]bool)
    for _, num := range lst {
        if num < min {
            min = num
        }
        if num > max {
            max = num
        }
        seen[num] = true
    }

    result := make([]int, 0, len(lst))
    for len(result) < len(lst) {
        result = append(result, min)
        delete(seen, min)

        if len(seen) == 0 {
            break
        }

        max = findNextMax(seen, max)
        result = append(result, max)
        delete(seen, max)

        if len(seen) == 0 {
            break
        }

        min = findNextMin(seen, min)
    }

    return result
}

func findNextMax(seen map[int]bool, prevMax int) int {
    for num := prevMax - 1; num > 0; num-- {
        if seen[num] {
            return num
        }
    }
    return prevMax
}

func findNextMin(seen map[int]bool, prevMin int) int {
    for num := prevMin + 1; num > 0; num++ {
        if seen[num] {
            return num
        }
    }
    return prevMin
}

