import (
	"strings"
)

func IsBored(S string) int {
    var boredomCount int
    sentences := strings.FieldsFunc(S, func(r rune) bool {
        return r == '.' || r == '!' || r == '?'
    })

    for _, sentence := range sentences {
        if strings.HasPrefix(strings.TrimSpace(sentence), "I") {
            boredomCount++
        }
    }

    return boredomCount
}

