func AnyInt(x, y, z interface{}) bool {
	xInt, ok1 := x.(int)
	yInt, ok2 := y.(int)
	zInt, ok3 := z.(int)

	if !ok1 || !ok2 || !ok3 {
		return false
	}

	return xInt == yInt+zInt || yInt == xInt+zInt || zInt == xInt+yInt
}

