func Encode(message string) string {
    encodedMessage := ""

    for _, char := range message {
        switch char {
        case 'a':
            encodedMessage += "c"
        case 'A':
            encodedMessage += "C"
        case 'e':
            encodedMessage += "g"
        case 'E':
            encodedMessage += "G"
        case 'i':
            encodedMessage += "k"
        case 'I':
