func RoundedAvg(n, m int) interface{} {
	if n > m {
		return -1
	}

	sum := 0
	count := 0
	for i := n; i <= m; i++ {
		sum += i
		count++
	}
	avg := sum / count
	return fmt.Sprintf("0b%b", avg)
}

