import (
	"sort"
)

func UniqueDigits(x []int) []int {
	res := make([]int, 0)
	for _, num := range x {
		odd := true
		for num > 0 {
			digit := num % 10
			if digit%2 == 0 {
				odd = false
				break
			}
			num /= 10
		}
		if odd {
			res = append(res, num)
		}
	}
	sort.Ints(res)
	return res
}

