	// Sort the filtered numbers
	sort.Ints(filtered)

	// Reverse the sorted numbers
	for i, j := 0, len(filtered)-1; i < j; i, j = i+1, j-1 {
		filtered[i], filtered[j] = filtered[j], filtered[i]
	}

	// Map integers to corresponding strings
	digitMap := map[int]string{
		1: "One",
		2: "Two",
		3: "Three",
		4: "Four",
		5: "Five",
		6: "Six",
		7: "Seven",
		8: "Eight",
		9: "Nine",
	}

	// Convert integers to string representations
	var result []string
	for _, num := range filtered {
		result = append(result, digitMap[num])
	}

	return result
}

