            validNums[num] = convertToWord(num)
        }
    }

    sortedNums := make([]string, 0, len(validNums))
    for i := 9; i >= 1; i-- {
        if val, ok := validNums[i]; ok {
            sortedNums = append(sortedNums, val)
        }
    }

