import (
	"sort"
	"strings"
)

func ReverseDelete(s, c string) [2]interface{} {
	sChars := strings.Split(s, "")
	cChars := strings.Split(c, "")

	sort.Strings(cChars)

	var result string
	for _, char := range sChars {
		if !binarySearch(cChars, char) {
			result += char
		}
	}

	return [2]interface{}{result, isPalindrome(result)}
}

func binarySearch(arr []string, target string) bool {
	low := 0
	high := len(arr) - 1

	for low <= high {
		mid := low + (high-low)/2

		if arr[mid] == target {
			return true
		} else if arr[mid] < target {
			low = mid + 1
		} else {
			high = mid - 1
		}
	}

	return false
}

func isPalindrome(s string) bool {
	runes := []rune(s)
	for i := 0; i < len(runes)/2; i++ {
		if runes[i] != runes[len(runes)-i-1] {
			return false
		}
	}
	return true
}

