	"sort"
)

func MaxFill(grid [][]int, capacity int) int {
    wells := make([]int, 0)

    for _, row := range grid {
        for _, val := range row {
            if val == 1 {
                wells = append(wells, 1)
            }
        }
    }

    bucketsNeeded := 0
    sort.Ints(wells)

    for i := len(wells) - 1; i >= 0; i -= capacity {
        bucketsNeeded++
    }

    return bucketsNeeded
}

