import (
	"unicode"
)

func GetClosestVowel(word string) string {
    vowels := "aeiouAEIOU"
    var closestVowel rune
    foundConsonant := false

    for i := len(word) - 2; i > 0; i-- {
        if unicode.IsLetter(rune(word[i])) {
            if !foundConsonant && vowelsContain(vowels, rune(word[i])) {
                closestVowel = rune(word[i])
                break
            } else if !foundConsonant {
                foundConsonant = true
            }
        }
    }

    return string(closestVowel)
}

func vowelsContain(vowels string, ch rune) bool {
    for _, v := range vowels {
        if v == ch {
            return true
        }
    }
    return false
}

