	"sort"
	"strings"
)

func GetClosestVowel(word string) string {
	vowels := "aeiouAEIOU"
	consonants := "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"

	var indices []int
	for i, r := range word {
		if strings.ContainsRune(consonants, r) {
			indices = append(indices, i)
		}
	}
	sort.Ints(indices)

	for i := len(indices) - 2; i > 0; i-- {
		if strings.ContainsRune(vowels, rune(word[indices[i]])) {
			return string(word[indices[i]])
		}
	}

	return ""
}

