func Maximum(arr []int, k int) []int {
    if k == 0 {
        return []int{}
    }

    countMap := make(map[int]int)
    for _, num := range arr {
        countMap[num]++
    }

    uniqueNums := make([]int, 0, len(countMap))
    for num := range countMap {
        uniqueNums = append(uniqueNums, num)
    }

    sort.Slice(uniqueNums, func(i, j int) bool {
        return countMap[uniqueNums[i]] > countMap[uniqueNums[j]] || 
            (countMap[uniqueNums[i]] == countMap[uniqueNums[j]] && uniqueNums[i] < uniqueNums[j])
    })

    return uniqueNums[:min(k, len(uniqueNums))]
}

