	"sort"
)

func Minpath(grid [][]int, k int) []int {
    n := len(grid)
    cells := make([]int, 0, n*n)
    for _, row := range grid {
        for _, val := range row {
            cells = append(cells, val)
        }
    }
    sort.Ints(cells)
    return cells[:k]
}

