func Minpath(grid [][]int, k int) []int {
	n := len(grid)
	result := make([]int, 0, k)
	x, y := 0, 0
	for i := 0; i < k; i++ {
		result = append(result, grid[x][y])
		if (x+y)%2 == 0 {
			if y < n-1 {
				y++
			} else {
				x++
			}
		} else {
			if y > 0 {
				y--
			} else {
				x++
			}
		}
	}
	return result
}

