    n := len(grid)
    var path []int

    for i := 0; i < k; i++ {
        row := i / n
        col := i % n
        if row%2 == 0 {
            path = append(path, grid[row][col])
        } else {
            path = append(path, grid[row][n-col-1])
        }
    }

    return path
}

