func CompareOne(a, b interface{}) interface{} {
    valueMap := make(map[interface{}]bool)

    valueMap[a] = true
    valueMap[b] = true

    if len(valueMap) == 1 {
        return nil
    }

    var larger interface{}

    for k := range valueMap {
        if larger == nil {
            larger = k
        } else {
            switch k.(type) {
            case int:
                if k.(int) > larger.(int) {
                    larger = k
                }
            case float64:
                if k.(float64) > larger.(float64) {
                    larger = k
