        return 1
    }

    result := 1
    nums := make([]int, n)
    for i := 0; i < n; i++ {
        nums[i] = i + 1
    }

    for i := 0; i < n; i++ {
        for j := 0; j < n-1; j++ {
            if nums[j] > nums[j+1] {
                nums[j], nums[j+1] = nums[j+1], nums[j]
            }
        }
    }

    for i := 0; i < n; i++ {
        result *= nums[i]
    }

    return result
}

