import (
	"strings"
)

func FixSpaces(text string) string {
	text = strings.ReplaceAll(text, " ", "_")

	var result strings.Builder
	consecutiveSpaces := 0

	for _, char := range text {
		if char == '_' {
			consecutiveSpaces++
			if consecutiveSpaces > 2 {
				result.WriteString("-")
				consecutiveSpaces = 0
			} else {
				result.WriteString("_")
			}
