	split := strings.Split(text, "_")
	sort.Slice(split, func(i, j int) bool {
		return len(split[i]) > len(split[j])
	})
	for i := 0; i < len(split); i++ {
		if len(split[i]) > 2 {
			text = strings.ReplaceAll(text, strings.Repeat("_", len(split[i])), "-")
		}
	}
	return text
}

