func Solve(s string) string {
    runes := []rune(s)
    hasLetters := false

    for i := 0; i < len(runes); i++ {
        if isLetter(runes[i]) {
            hasLetters = true
            if isLower(runes[i]) {
                runes[i] = toUpper(runes[i])
            } else {
                runes[i] = toLower(runes[i])
            }
        }
    }

